            if is_digit1 and is_digit2:
                # Both numeric: compare numerically
                cmp = int(id1) - int(id2)
                if cmp != 0:
                    return cmp
            elif is_digit1:
                # Numeric sorts before non-numeric
                return -1
            elif is_digit2:
                # Non-numeric sorts after numeric
                return 1
            else:
                # Both non-numeric: compare by ASCII order
                if id1 < id2:
                    return -1
                elif id1 > id2:
                    return 1

        # All shared identifiers are equal, fewer identifiers sort first
        if len(pre1) < len(pre2):
            return -1
        elif len(pre1) > len(pre2):
            return 1
        return 0

    def sort_key(version):
        # Parse version to get sortable tuple
        # We need a key that maintains stable sort for equal precedence
        major, minor, patch, prerelease = parse_version(version)

        # Create a tuple for primary sorting
        # For pre-release comparison, we need to convert to something comparable
        if prerelease is None:
            # No pre-release: sorts after any pre-release of same version
            prerelease_key = (1,)  # Higher sort value
        else:
            # Has pre-release: sorts before no pre-release
            prerelease_key = (0,) + tuple(
